class Connection(dict):
    """SSH connection parameters container."""

    def __init__(self):
        super(Connection, self).__init__(username='ute', password='ute', host='127.0.0.1')

    def __getattr__(self, item):
        if item in self:
            return self[item]

    def __setattr__(self, key, value):
        if key in self:
            self[key] = value
        super(Connection, self).__setattr__(key, value)
